insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-ancient-greece-trivia',
  'Ancient Greece Trivia: Polis, Philosophers and Wars',
  'Eight questions on the city-states, thinkers and wars of ancient Greece, from the first Olympics to the Peloponnesian War.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"What did the ancient Greeks call their independent city-states?","options":[{"id":"a","text":"Agoras","is_correct":false},{"id":"b","text":"Polis","is_correct":true},{"id":"c","text":"Acropolis","is_correct":false},{"id":"d","text":"Demos","is_correct":false}],"explanation":"From Athens to Sparta, each polis was a self-governing city-state with its own laws and army."},{"id":"q2","question":"Which Greek city-state is considered the birthplace of democracy?","options":[{"id":"a","text":"Sparta","is_correct":false},{"id":"b","text":"Corinth","is_correct":false},{"id":"c","text":"Athens","is_correct":true},{"id":"d","text":"Thebes","is_correct":false}],"explanation":"After Cleisthenes'' reforms around 508 BC, the male citizens of Athens voted directly on laws in the assembly."},{"id":"q3","question":"Which war (431-404 BC) pitted Athens and its allies against Sparta''s league?","options":[{"id":"a","text":"The Trojan War","is_correct":false},{"id":"b","text":"The Greco-Persian Wars","is_correct":false},{"id":"c","text":"The Corinthian War","is_correct":false},{"id":"d","text":"The Peloponnesian War","is_correct":true}],"explanation":"Thucydides chronicled the 27-year struggle that ended with Athens'' surrender to Sparta in 404 BC."},{"id":"q4","question":"Which philosopher was sentenced to death by drinking hemlock in 399 BC?","options":[{"id":"a","text":"Socrates","is_correct":true},{"id":"b","text":"Plato","is_correct":false},{"id":"c","text":"Aristotle","is_correct":false},{"id":"d","text":"Diogenes","is_correct":false}],"explanation":"An Athenian jury convicted Socrates of impiety and corrupting the youth; Plato recorded his trial in the Apology."},{"id":"q5","question":"Who is credited with composing the epic poems the Iliad and the Odyssey?","options":[{"id":"a","text":"Hesiod","is_correct":false},{"id":"b","text":"Sophocles","is_correct":false},{"id":"c","text":"Homer","is_correct":true},{"id":"d","text":"Aeschylus","is_correct":false}],"explanation":"Tradition attributes both epics to Homer, a poet believed to have lived around the 8th century BC."},{"id":"q6","question":"Where were the ancient Olympic Games held every four years from 776 BC?","options":[{"id":"a","text":"Delphi","is_correct":false},{"id":"b","text":"Olympia","is_correct":true},{"id":"c","text":"Nemea","is_correct":false},{"id":"d","text":"Corinth","is_correct":false}],"explanation":"The games honoured Zeus at Olympia; winners received an olive wreath, not medals."},{"id":"q7","question":"At which 480 BC battle did a small Greek force led by 300 Spartans hold a pass against the Persians?","options":[{"id":"a","text":"Marathon","is_correct":false},{"id":"b","text":"Salamis","is_correct":false},{"id":"c","text":"Thermopylae","is_correct":true},{"id":"d","text":"Plataea","is_correct":false}],"explanation":"King Leonidas and his Spartans delayed Xerxes'' army at Thermopylae until a local revealed a flanking path."},{"id":"q8","question":"Which Athenian statesman led the city during its Golden Age in the 5th century BC?","options":[{"id":"a","text":"Solon","is_correct":false},{"id":"b","text":"Pericles","is_correct":true},{"id":"c","text":"Themistocles","is_correct":false},{"id":"d","text":"Cleisthenes","is_correct":false}],"explanation":"Under Pericles, Athens rebuilt the Acropolis with the Parthenon and expanded its citizen-led democracy."}]'::jsonb,
  null,
  array['history', 'trivia', 'ancient greece', 'antiquity']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
