values (
  'es-trivia-antigua-grecia',
  'Trivia de la Antigua Grecia: polis, filósofos y guerras',
  'Ocho preguntas sobre las polis, los filósofos y las guerras de la Antigua Grecia, de las primeras Olimpiadas a la guerra del Peloponeso.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Cómo llamaban los antiguos griegos a sus ciudades-Estado independientes?","options":[{"id":"a","text":"Ágoras","is_correct":false},{"id":"b","text":"Acrópolis","is_correct":false},{"id":"c","text":"Polis","is_correct":true},{"id":"d","text":"Demos","is_correct":false}],"explanation":"De Atenas a Esparta, cada polis era una ciudad-Estado autónoma con sus propias leyes y ejército."},{"id":"q2","question":"¿Qué ciudad-Estado griega es considerada la cuna de la democracia?","options":[{"id":"a","text":"Esparta","is_correct":false},{"id":"b","text":"Corinto","is_correct":false},{"id":"c","text":"Tebas","is_correct":false},{"id":"d","text":"Atenas","is_correct":true}],"explanation":"Tras las reformas de Clístenes hacia 508 a. C., los ciudadanos de Atenas votaban las leyes en la asamblea."},{"id":"q3","question":"¿Qué guerra (431-404 a. C.) enfrentó a Atenas y sus aliados con la liga de Esparta?","options":[{"id":"a","text":"La guerra de Troya","is_correct":false},{"id":"b","text":"Las guerras médicas","is_correct":false},{"id":"c","text":"La guerra del Peloponeso","is_correct":true},{"id":"d","text":"La guerra de Corinto","is_correct":false}],"explanation":"Tucídides narró el conflicto de 27 años que terminó con la rendición de Atenas ante Esparta en 404 a. C."},{"id":"q4","question":"¿Qué filósofo fue condenado a muerte bebiendo cicuta en 399 a. C.?","options":[{"id":"a","text":"Platón","is_correct":false},{"id":"b","text":"Sócrates","is_correct":true},{"id":"c","text":"Aristóteles","is_correct":false},{"id":"d","text":"Diógenes","is_correct":false}],"explanation":"Un jurado ateniense condenó a Sócrates por impiedad y corromper a la juventud; Platón recogió su juicio en la Apología."},{"id":"q5","question":"¿A quién se atribuye la composición de los poemas épicos Ilíada y Odisea?","options":[{"id":"a","text":"Hesíodo","is_correct":false},{"id":"b","text":"Sófocles","is_correct":false},{"id":"c","text":"Esquilo","is_correct":false},{"id":"d","text":"Homero","is_correct":true}],"explanation":"La tradición atribuye ambas epopeyas a Homero, un poeta que habría vivido hacia el siglo VIII a. C."},{"id":"q6","question":"¿Dónde se celebraban los Juegos Olímpicos antiguos cada cuatro años desde 776 a. C.?","options":[{"id":"a","text":"Olimpia","is_correct":true},{"id":"b","text":"Delfos","is_correct":false},{"id":"c","text":"Nemea","is_correct":false},{"id":"d","text":"Corinto","is_correct":false}],"explanation":"Los juegos honraban a Zeus en Olimpia; los vencedores recibían una corona de olivo, no medallas."},{"id":"q7","question":"¿En qué batalla de 480 a. C. una pequeña fuerza griega liderada por 300 espartanos resistió a los persas en un desfiladero?","options":[{"id":"a","text":"Maratón","is_correct":false},{"id":"b","text":"Salamina","is_correct":false},{"id":"c","text":"Platea","is_correct":false},{"id":"d","text":"Termópilas","is_correct":true}],"explanation":"El rey Leónidas y sus espartanos frenaron al ejército de Jerjes en las Termópilas hasta que un lugareño reveló un sendero para rodearlos."},{"id":"q8","question":"¿Qué estadista ateniense dirigió la ciudad durante su Siglo de Oro en el siglo V a. C.?","options":[{"id":"a","text":"Solón","is_correct":false},{"id":"b","text":"Temístocles","is_correct":false},{"id":"c","text":"Pericles","is_correct":true},{"id":"d","text":"Clístenes","is_correct":false}],"explanation":"Bajo Pericles, Atenas reconstruyó la Acrópolis con el Partenón y amplió su democracia ciudadana."}]'::jsonb,
  null,
  array['historia', 'trivia', 'antigua grecia', 'antigüedad']::text[],
  3,
  'published',
  false,
  false,
  now()
)
