insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-mesopotamia-trivia',
  'Mesopotamia Trivia: The Cradle of Civilization',
  'Eight questions on Sumer, Babylon and the empires of Mesopotamia: cuneiform writing, law codes and the first cities.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Mesopotamia means ''land between rivers''. Which two rivers does the name refer to?","options":[{"id":"a","text":"The Nile and the Tigris","is_correct":false},{"id":"b","text":"The Tigris and the Euphrates","is_correct":true},{"id":"c","text":"The Euphrates and the Indus","is_correct":false},{"id":"d","text":"The Jordan and the Euphrates","is_correct":false}],"explanation":"The Greek name describes the plain between the Tigris and the Euphrates, mostly within present-day Iraq."},{"id":"q2","question":"Which people built Mesopotamia''s first great cities, such as Uruk and Ur?","options":[{"id":"a","text":"The Akkadians","is_correct":false},{"id":"b","text":"The Babylonians","is_correct":false},{"id":"c","text":"The Sumerians","is_correct":true},{"id":"d","text":"The Hittites","is_correct":false}],"explanation":"By around 3500 BC the Sumerians had turned southern Mesopotamia into a land of walled city-states."},{"id":"q3","question":"What writing system did Mesopotamian scribes press into clay tablets with reeds?","options":[{"id":"a","text":"Hieroglyphics","is_correct":false},{"id":"b","text":"Cuneiform","is_correct":true},{"id":"c","text":"Linear B","is_correct":false},{"id":"d","text":"The Phoenician alphabet","is_correct":false}],"explanation":"Cuneiform''s wedge-shaped marks recorded everything from grain accounts to royal decrees for three millennia."},{"id":"q4","question":"Which Babylonian king issued a famous law code carved on a stone stele around 1750 BC?","options":[{"id":"a","text":"Sargon of Akkad","is_correct":false},{"id":"b","text":"Hammurabi","is_correct":true},{"id":"c","text":"Nebuchadnezzar II","is_correct":false},{"id":"d","text":"Ashurbanipal","is_correct":false}],"explanation":"The Code of Hammurabi''s 282 laws spelled out penalties like ''an eye for an eye'' and were displayed publicly."},{"id":"q5","question":"Which epic follows King Gilgamesh of Uruk on his search for immortality?","options":[{"id":"a","text":"The Epic of Gilgamesh","is_correct":true},{"id":"b","text":"Enuma Elish","is_correct":false},{"id":"c","text":"The Atrahasis","is_correct":false},{"id":"d","text":"The Descent of Inanna","is_correct":false}],"explanation":"Written in Akkadian cuneiform, it is one of the oldest works of literature known."},{"id":"q6","question":"Who created history''s first empire by uniting Sumer and Akkad around 2330 BC?","options":[{"id":"a","text":"Hammurabi","is_correct":false},{"id":"b","text":"Ur-Nammu","is_correct":false},{"id":"c","text":"Sargon of Akkad","is_correct":true},{"id":"d","text":"Tiglath-Pileser I","is_correct":false}],"explanation":"Sargon''s conquests bound northern and southern Mesopotamia into one state ruled from Akkad."},{"id":"q7","question":"Which king rebuilt Babylon in the 6th century BC and is traditionally linked to the Hanging Gardens?","options":[{"id":"a","text":"Hammurabi","is_correct":false},{"id":"b","text":"Sargon II","is_correct":false},{"id":"c","text":"Nebuchadnezzar II","is_correct":true},{"id":"d","text":"Cyrus the Great","is_correct":false}],"explanation":"Nebuchadnezzar II rebuilt Babylon''s walls and the Ishtar Gate; Greek authors credited him with the gardens."},{"id":"q8","question":"In which Assyrian capital did Ashurbanipal assemble a great library of clay tablets?","options":[{"id":"a","text":"Babylon","is_correct":false},{"id":"b","text":"Nineveh","is_correct":true},{"id":"c","text":"Uruk","is_correct":false},{"id":"d","text":"Eridu","is_correct":false}],"explanation":"The library of Nineveh held tens of thousands of tablets, including a copy of the Epic of Gilgamesh."}]'::jsonb,
  null,
  array['history', 'trivia', 'mesopotamia', 'antiquity']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-mesopotamia',
  'Trivia de Mesopotamia: la cuna de la civilización',
  'Ocho preguntas sobre Sumer, Babilonia y los imperios de Mesopotamia: escritura cuneiforme, códigos de leyes y las primeras ciudades.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Mesopotamia significa «tierra entre ríos». ¿A qué dos ríos se refiere el nombre?","options":[{"id":"a","text":"El Nilo y el Tigris","is_correct":false},{"id":"b","text":"El Tigris y el Éufrates","is_correct":true},{"id":"c","text":"El Éufrates y el Indo","is_correct":false},{"id":"d","text":"El Jordán y el Éufrates","is_correct":false}],"explanation":"El nombre griego describe la llanura entre el Tigris y el Éufrates, hoy mayoritariamente en Irak."},{"id":"q2","question":"¿Qué pueblo levantó las primeras grandes ciudades de Mesopotamia, como Uruk y Ur?","options":[{"id":"a","text":"Los acadios","is_correct":false},{"id":"b","text":"Los babilonios","is_correct":false},{"id":"c","text":"Los hititas","is_correct":false},{"id":"d","text":"Los sumerios","is_correct":true}],"explanation":"Hacia 3500 a. C. los sumerios convirtieron el sur de Mesopotamia en un paisaje de ciudades-Estado amuralladas."},{"id":"q3","question":"¿Qué escritura marcaban los escribas mesopotámicos con cañas sobre tablillas de arcilla?","options":[{"id":"a","text":"Los jeroglíficos","is_correct":false},{"id":"b","text":"El lineal B","is_correct":false},{"id":"c","text":"La cuneiforme","is_correct":true},{"id":"d","text":"El alfabeto fenicio","is_correct":false}],"explanation":"Los trazos en cuña del cuneiforme registraron desde cuentas de grano hasta decretos reales durante tres milenios."},{"id":"q4","question":"¿Qué rey de Babilonia promulgó un célebre código de leyes grabado en una estela hacia 1750 a. C.?","options":[{"id":"a","text":"Sargón de Acad","is_correct":false},{"id":"b","text":"Nabucodonosor II","is_correct":false},{"id":"c","text":"Hammurabi","is_correct":true},{"id":"d","text":"Asurbanipal","is_correct":false}],"explanation":"Las 282 leyes del código de Hammurabi fijaban castigos como el «ojo por ojo» y se exhibían en público."},{"id":"q5","question":"¿Qué epopeya sigue al rey Gilgamesh de Uruk en su búsqueda de la inmortalidad?","options":[{"id":"a","text":"Enuma Elish","is_correct":false},{"id":"b","text":"La Epopeya de Gilgamesh","is_correct":true},{"id":"c","text":"El Poema de Atrajasis","is_correct":false},{"id":"d","text":"El descenso de Inanna","is_correct":false}],"explanation":"Escrita en cuneiforme acadio, es una de las obras literarias más antiguas que se conocen."},{"id":"q6","question":"¿Quién creó el primer imperio de la historia al unir Sumer y Acad hacia 2330 a. C.?","options":[{"id":"a","text":"Hammurabi","is_correct":false},{"id":"b","text":"Ur-Nammu","is_correct":false},{"id":"c","text":"Tiglat-Pileser I","is_correct":false},{"id":"d","text":"Sargón de Acad","is_correct":true}],"explanation":"Las conquistas de Sargón unieron el norte y el sur de Mesopotamia en un solo Estado gobernado desde Acad."},{"id":"q7","question":"¿Qué rey reconstruyó Babilonia en el siglo VI a. C. y se asocia tradicionalmente a los Jardines Colgantes?","options":[{"id":"a","text":"Hammurabi","is_correct":false},{"id":"b","text":"Sargón II","is_correct":false},{"id":"c","text":"Nabucodonosor II","is_correct":true},{"id":"d","text":"Ciro el Grande","is_correct":false}],"explanation":"Nabucodonosor II reconstruyó las murallas y la puerta de Istar; los autores griegos le atribuyeron los jardines."},{"id":"q8","question":"¿En qué capital asiria reunió Asurbanipal una gran biblioteca de tablillas de arcilla?","options":[{"id":"a","text":"Babilonia","is_correct":false},{"id":"b","text":"Uruk","is_correct":false},{"id":"c","text":"Éridu","is_correct":false},{"id":"d","text":"Nínive","is_correct":true}],"explanation":"La biblioteca de Nínive guardaba decenas de miles de tablillas, incluida una copia de la Epopeya de Gilgamesh."}]'::jsonb,
  null,
  array['historia', 'trivia', 'mesopotamia', 'antigüedad']::text[],
  3,
  'published',
  false,
  false,
  now()
)
