insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-seven-wonders-trivia',
  'Seven Wonders Trivia: Marvels of the Ancient World',
  'Eight questions on the Seven Wonders of the Ancient World: what they were, where they stood and what survives today.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Which of the Seven Wonders of the Ancient World is the only one still standing?","options":[{"id":"a","text":"The Colossus of Rhodes","is_correct":false},{"id":"b","text":"The Great Pyramid of Giza","is_correct":true},{"id":"c","text":"The Lighthouse of Alexandria","is_correct":false},{"id":"d","text":"The Statue of Zeus at Olympia","is_correct":false}],"explanation":"Built around 2560 BC for Pharaoh Khufu, the Great Pyramid is nearly 4,600 years old."},{"id":"q2","question":"The Colossus was a giant bronze statue of the sun god Helios in which harbour city?","options":[{"id":"a","text":"Ephesus","is_correct":false},{"id":"b","text":"Rhodes","is_correct":true},{"id":"c","text":"Alexandria","is_correct":false},{"id":"d","text":"Halicarnassus","is_correct":false}],"explanation":"Raised to celebrate Rhodes'' defence against a siege, the Colossus stood for only 54 years before an earthquake."},{"id":"q3","question":"Which wonder was a marble temple in Ephesus dedicated to a goddess of the hunt?","options":[{"id":"a","text":"The Temple of Artemis","is_correct":true},{"id":"b","text":"The Parthenon","is_correct":false},{"id":"c","text":"The Mausoleum","is_correct":false},{"id":"d","text":"The Pharos","is_correct":false}],"explanation":"The Temple of Artemis was rebuilt after an arsonist burned it in 356 BC, the night legend says Alexander the Great was born."},{"id":"q4","question":"Which wonder was a towering lighthouse that guided ships into an Egyptian harbour?","options":[{"id":"a","text":"The Pharos of Alexandria","is_correct":true},{"id":"b","text":"The Tower of Babel","is_correct":false},{"id":"c","text":"The Colossus of Rhodes","is_correct":false},{"id":"d","text":"The Temple of Artemis","is_correct":false}],"explanation":"Built under Ptolemy II around 280 BC, the Pharos stood on an island off Alexandria until earthquakes toppled it."},{"id":"q5","question":"The Mausoleum at Halicarnassus was the tomb of which ruler, whose name gave us the word ''mausoleum''?","options":[{"id":"a","text":"Alexander the Great","is_correct":false},{"id":"b","text":"Darius I","is_correct":false},{"id":"c","text":"Croesus","is_correct":false},{"id":"d","text":"Mausolus","is_correct":true}],"explanation":"Mausolus ruled Caria in the 4th century BC; his widow Artemisia finished the monument after his death."},{"id":"q6","question":"In which city were the Hanging Gardens said to have been built for a homesick queen?","options":[{"id":"a","text":"Babylon","is_correct":true},{"id":"b","text":"Nineveh","is_correct":false},{"id":"c","text":"Persepolis","is_correct":false},{"id":"d","text":"Memphis","is_correct":false}],"explanation":"Tradition credits Nebuchadnezzar II with the gardens for Queen Amytis, though some scholars place them in Nineveh."},{"id":"q7","question":"Which sculptor, also behind the Parthenon''s statue of Athena, made the Statue of Zeus at Olympia?","options":[{"id":"a","text":"Praxiteles","is_correct":false},{"id":"b","text":"Phidias","is_correct":true},{"id":"c","text":"Myron","is_correct":false},{"id":"d","text":"Polykleitos","is_correct":false}],"explanation":"Phidias'' seated Zeus, made of ivory and gold, was about 12 metres tall; visitors said it seemed ready to stand."},{"id":"q8","question":"Which of the Seven Wonders stood furthest east?","options":[{"id":"a","text":"The Statue of Zeus at Olympia","is_correct":false},{"id":"b","text":"The Temple of Artemis at Ephesus","is_correct":false},{"id":"c","text":"The Hanging Gardens of Babylon","is_correct":true},{"id":"d","text":"The Lighthouse of Alexandria","is_correct":false}],"explanation":"Babylon, in present-day Iraq, lay far inland on the Euphrates, much further east than the wonders of Greece, Anatolia and Egypt."}]'::jsonb,
  null,
  array['history', 'trivia', 'seven wonders', 'antiquity']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-siete-maravillas-del-mundo',
  'Trivia de las siete maravillas: de Guiza a Alejandría',
  'Ocho preguntas sobre las siete maravillas del mundo antiguo: qué eran, dónde estaban y qué queda de ellas.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Cuál de las siete maravillas del mundo antiguo es la única que sigue en pie?","options":[{"id":"a","text":"El Coloso de Rodas","is_correct":false},{"id":"b","text":"El Faro de Alejandría","is_correct":false},{"id":"c","text":"La Gran Pirámide de Guiza","is_correct":true},{"id":"d","text":"La estatua de Zeus en Olimpia","is_correct":false}],"explanation":"Construida hacia 2560 a. C. para el faraón Keops, la Gran Pirámide tiene casi 4.600 años."},{"id":"q2","question":"El Coloso era una gigantesca estatua de bronce del dios Helios. ¿En qué ciudad portuaria estaba?","options":[{"id":"a","text":"Éfeso","is_correct":false},{"id":"b","text":"Rodas","is_correct":true},{"id":"c","text":"Alejandría","is_correct":false},{"id":"d","text":"Halicarnaso","is_correct":false}],"explanation":"Erigido para celebrar la defensa de Rodas contra un asedio, el Coloso solo duró 54 años antes de un terremoto."},{"id":"q3","question":"¿Qué maravilla era un templo de mármol en Éfeso dedicado a la diosa de la caza?","options":[{"id":"a","text":"El Partenón","is_correct":false},{"id":"b","text":"El Templo de Artemisa","is_correct":true},{"id":"c","text":"El Mausoleo","is_correct":false},{"id":"d","text":"El Faro","is_correct":false}],"explanation":"El Templo de Artemisa ardió en 356 a. C., la noche en que la leyenda dice que nació Alejandro Magno, y fue reconstruido."},{"id":"q4","question":"¿Qué maravilla era un faro gigantesco que guiaba los barcos hacia un puerto egipcio?","options":[{"id":"a","text":"La torre de Babel","is_correct":false},{"id":"b","text":"El Coloso de Rodas","is_correct":false},{"id":"c","text":"El Faro de Alejandría","is_correct":true},{"id":"d","text":"El Templo de Artemisa","is_correct":false}],"explanation":"Construido bajo Ptolomeo II hacia 280 a. C., el Faro se alzó en una isla frente a Alejandría hasta que los terremotos lo derribaron."},{"id":"q5","question":"El Mausoleo de Halicarnaso era la tumba de qué gobernante, cuyo nombre dio origen a la palabra «mausoleo»?","options":[{"id":"a","text":"Alejandro Magno","is_correct":false},{"id":"b","text":"Darío I","is_correct":false},{"id":"c","text":"Creso","is_correct":false},{"id":"d","text":"Mausolo","is_correct":true}],"explanation":"Mausolo gobernó Caria en el siglo IV a. C.; su viuda Artemisia terminó el monumento tras su muerte."},{"id":"q6","question":"¿En qué ciudad se decía que estaban los Jardines Colgantes, construidos para una reina nostálgica?","options":[{"id":"a","text":"Nínive","is_correct":false},{"id":"b","text":"Persépolis","is_correct":false},{"id":"c","text":"Babilonia","is_correct":true},{"id":"d","text":"Menfis","is_correct":false}],"explanation":"La tradición atribuye los jardines a Nabucodonosor II para la reina Amytis, aunque algunos estudiosos los sitúan en Nínive."},{"id":"q7","question":"¿Qué escultor, autor también de la estatua de Atenea del Partenón, hizo la estatua de Zeus en Olimpia?","options":[{"id":"a","text":"Praxíteles","is_correct":false},{"id":"b","text":"Mirón","is_correct":false},{"id":"c","text":"Policleto","is_correct":false},{"id":"d","text":"Fidias","is_correct":true}],"explanation":"El Zeus sentado de Fidias, de marfil y oro, medía unos 12 metros; quienes lo veían decían que parecía a punto de levantarse."},{"id":"q8","question":"¿Qué maravilla se ubicaba más al este de las siete?","options":[{"id":"a","text":"La estatua de Zeus en Olimpia","is_correct":false},{"id":"b","text":"El Templo de Artemisa en Éfeso","is_correct":false},{"id":"c","text":"El Faro de Alejandría","is_correct":false},{"id":"d","text":"Los Jardines Colgantes de Babilonia","is_correct":true}],"explanation":"Babilonia, en el actual Irak, estaba tierra adentro sobre el Éufrates, mucho más al este que las maravillas de Grecia, Anatolia y Egipto."}]'::jsonb,
  null,
  array['historia', 'trivia', 'siete maravillas', 'antigüedad']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-empires-that-reshaped-the-world-trivia',
  'World Empires Trivia: Conquests That Reshaped History',
  'Eight questions on the Persian, Macedonian, Mongol, Ottoman and British empires: conquests, rulers and legacies.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Cyrus the Great founded which empire, which by 500 BC stretched from Anatolia to the Indus?","options":[{"id":"a","text":"The Ottoman Empire","is_correct":false},{"id":"b","text":"The Assyrian Empire","is_correct":false},{"id":"c","text":"The Persian Empire","is_correct":true},{"id":"d","text":"The Seleucid Empire","is_correct":false}],"explanation":"The Achaemenid Persians ruled satrapies linked by the Royal Road; Cyrus'' cylinder is famous for its decree on exiles."},{"id":"q2","question":"Which king of Macedon conquered an empire from Greece to India before dying at 32 in 323 BC?","options":[{"id":"a","text":"Philip II","is_correct":false},{"id":"b","text":"Alexander the Great","is_correct":true},{"id":"c","text":"Pyrrhus","is_correct":false},{"id":"d","text":"Darius III","is_correct":false}],"explanation":"In thirteen years Alexander toppled Persia, reached the Indus and founded cities like Alexandria."},{"id":"q3","question":"Founded by Genghis Khan in 1206, which empire became the largest contiguous land empire in history?","options":[{"id":"a","text":"The Mongol Empire","is_correct":true},{"id":"b","text":"The Ottoman Empire","is_correct":false},{"id":"c","text":"The Russian Empire","is_correct":false},{"id":"d","text":"The Qing Empire","is_correct":false}],"explanation":"At its peak the Mongol Empire ran from Korea to Hungary, united under one legal code and a relay-post system."},{"id":"q4","question":"Which city''s fall to Mehmed II in 1453 ended the Byzantine Empire and crowned Ottoman power?","options":[{"id":"a","text":"Rome","is_correct":false},{"id":"b","text":"Baghdad","is_correct":false},{"id":"c","text":"Constantinople","is_correct":true},{"id":"d","text":"Cairo","is_correct":false}],"explanation":"After a 53-day siege, Ottoman cannons breached the Theodosian Walls and Constantinople became Istanbul."},{"id":"q5","question":"Around 1920, at its peak, the British Empire covered roughly what share of Earth''s land surface?","options":[{"id":"a","text":"One tenth","is_correct":false},{"id":"b","text":"One quarter","is_correct":true},{"id":"c","text":"One half","is_correct":false},{"id":"d","text":"One third","is_correct":false}],"explanation":"About a quarter of the world''s land and a similar share of its population were under British rule at the empire''s height."},{"id":"q6","question":"Which Roman emperor''s reign from 27 BC began the two centuries of stability called the Pax Romana?","options":[{"id":"a","text":"Nero","is_correct":false},{"id":"b","text":"Augustus","is_correct":true},{"id":"c","text":"Trajan","is_correct":false},{"id":"d","text":"Constantine","is_correct":false}],"explanation":"Octavian, renamed Augustus, ended the civil wars and set the frontiers that defined the empire for generations."},{"id":"q7","question":"Kublai Khan, grandson of Genghis Khan, founded which dynasty that ruled China?","options":[{"id":"a","text":"Ming","is_correct":false},{"id":"b","text":"Han","is_correct":false},{"id":"c","text":"Yuan","is_correct":true},{"id":"d","text":"Qing","is_correct":false}],"explanation":"Kublai moved his capital to Dadu (today''s Beijing) and ruled China in imperial style as the Yuan dynasty."},{"id":"q8","question":"Which 732 battle is traditionally credited with stopping the Umayyad advance into Frankish Europe?","options":[{"id":"a","text":"The Battle of Tours","is_correct":true},{"id":"b","text":"The Battle of Hastings","is_correct":false},{"id":"c","text":"The Battle of Lepanto","is_correct":false},{"id":"d","text":"The Battle of Manzikert","is_correct":false}],"explanation":"Charles Martel''s infantry repelled the Umayyad force between Tours and Poitiers, halting its expansion into Francia."}]'::jsonb,
  null,
  array['history', 'trivia', 'empires', 'world history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-imperios-que-cambiaron-el-mundo',
  'Trivia de imperios: conquistas que cambiaron el mundo',
  'Ocho preguntas sobre los imperios persa, macedonio, mongol, otomano y británico: conquistas, gobernantes y legados.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Ciro el Grande fundó qué imperio, que hacia 500 a. C. se extendía de Anatolia al Indo?","options":[{"id":"a","text":"El Imperio otomano","is_correct":false},{"id":"b","text":"El Imperio asirio","is_correct":false},{"id":"c","text":"El Imperio seléucida","is_correct":false},{"id":"d","text":"El Imperio persa","is_correct":true}],"explanation":"Los persas aqueménidas gobernaban satrapías unidas por el Camino Real; el cilindro de Ciro es famoso por su decreto sobre los exiliados."},{"id":"q2","question":"¿Qué rey de Macedonia conquistó un imperio de Grecia a la India antes de morir a los 32 años en 323 a. C.?","options":[{"id":"a","text":"Filipo II","is_correct":false},{"id":"b","text":"Pirro","is_correct":false},{"id":"c","text":"Alejandro Magno","is_correct":true},{"id":"d","text":"Darío III","is_correct":false}],"explanation":"En trece años, Alejandro derrocó a Persia, llegó al Indo y fundó ciudades como Alejandría."},{"id":"q3","question":"Fundado por Gengis Kan en 1206, ¿qué imperio llegó a ser el mayor imperio terrestre continuo de la historia?","options":[{"id":"a","text":"El Imperio otomano","is_correct":false},{"id":"b","text":"El Imperio mongol","is_correct":true},{"id":"c","text":"El Imperio ruso","is_correct":false},{"id":"d","text":"El Imperio Qing","is_correct":false}],"explanation":"En su apogeo, el Imperio mongol iba de Corea a Hungría, unido por un mismo código legal y un sistema de postas."},{"id":"q4","question":"¿Qué ciudad cayó en 1453 ante Mehmed II, poniendo fin al Imperio bizantino y coronando el poder otomano?","options":[{"id":"a","text":"Roma","is_correct":false},{"id":"b","text":"Bagdad","is_correct":false},{"id":"c","text":"El Cairo","is_correct":false},{"id":"d","text":"Constantinopla","is_correct":true}],"explanation":"Tras un asedio de 53 días, los cañones otomanos abrieron brecha en las murallas de Teodosio y Constantinopla pasó a ser Estambul."},{"id":"q5","question":"Hacia 1920, en su apogeo, ¿qué parte de la tierra emergida cubría aproximadamente el Imperio británico?","options":[{"id":"a","text":"Una décima parte","is_correct":false},{"id":"b","text":"Una cuarta parte","is_correct":true},{"id":"c","text":"La mitad","is_correct":false},{"id":"d","text":"Un tercio","is_correct":false}],"explanation":"Cerca de una cuarta parte de las tierras del mundo y una proporción similar de su población estaban bajo dominio británico."},{"id":"q6","question":"¿Qué emperador romano inició con su reinado desde 27 a. C. los dos siglos de estabilidad llamados Pax Romana?","options":[{"id":"a","text":"Nerón","is_correct":false},{"id":"b","text":"Trajano","is_correct":false},{"id":"c","text":"Augusto","is_correct":true},{"id":"d","text":"Constantino","is_correct":false}],"explanation":"Octavio, rebautizado como Augusto, acabó con las guerras civiles y fijó las fronteras que marcaron al imperio por generaciones."},{"id":"q7","question":"Kublai Kan, nieto de Gengis Kan, fundó qué dinastía que gobernó China?","options":[{"id":"a","text":"Ming","is_correct":false},{"id":"b","text":"Han","is_correct":false},{"id":"c","text":"Qing","is_correct":false},{"id":"d","text":"Yuan","is_correct":true}],"explanation":"Kublai trasladó su capital a Dadu (la actual Pekín) y gobernó China con estilo imperial como dinastía Yuan."},{"id":"q8","question":"¿Qué batalla de 732 se considera tradicionalmente la que detuvo el avance omeya en la Europa franca?","options":[{"id":"a","text":"La batalla de Hastings","is_correct":false},{"id":"b","text":"La batalla de Poitiers","is_correct":true},{"id":"c","text":"La batalla de Lepanto","is_correct":false},{"id":"d","text":"La batalla de Manzikert","is_correct":false}],"explanation":"La infantería de Carlos Martel rechazó a la fuerza omeya entre Tours y Poitiers, frenando su expansión hacia la Galia."}]'::jsonb,
  null,
  array['historia', 'trivia', 'imperios', 'historia universal']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-natural-wonders-trivia',
  'Natural Wonders Trivia: Earth''s Record-Breaking Places',
  'Eight questions on Earth''s most extreme natural wonders: the highest falls, the deepest lake, the largest reef and more.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"Which is the largest coral reef system on Earth, stretching about 2,300 km off Queensland?","options":[{"id":"a","text":"The Mesoamerican Reef","is_correct":false},{"id":"b","text":"The Great Barrier Reef","is_correct":true},{"id":"c","text":"The Red Sea reefs","is_correct":false},{"id":"d","text":"The New Caledonia barrier reef","is_correct":false}],"explanation":"The Great Barrier Reef joins nearly 3,000 individual reefs, the largest structure ever built by living organisms."},{"id":"q2","question":"Which is the world''s highest uninterrupted waterfall?","options":[{"id":"a","text":"Iguazú Falls","is_correct":false},{"id":"b","text":"Niagara Falls","is_correct":false},{"id":"c","text":"Angel Falls","is_correct":true},{"id":"d","text":"Victoria Falls","is_correct":false}],"explanation":"Angel Falls drops 979 metres from the Auyán-tepui plateau in Venezuela''s Canaima National Park."},{"id":"q3","question":"Which canyon, carved by the Colorado River, runs about 446 km through Arizona?","options":[{"id":"a","text":"The Grand Canyon","is_correct":true},{"id":"b","text":"Colca Canyon","is_correct":false},{"id":"c","text":"Copper Canyon","is_correct":false},{"id":"d","text":"Fish River Canyon","is_correct":false}],"explanation":"The Grand Canyon''s rock layers record nearly two billion years of Earth''s history."},{"id":"q4","question":"Which is the largest hot desert on Earth?","options":[{"id":"a","text":"The Gobi Desert","is_correct":false},{"id":"b","text":"The Atacama Desert","is_correct":false},{"id":"c","text":"The Arabian Desert","is_correct":false},{"id":"d","text":"The Sahara","is_correct":true}],"explanation":"The Sahara covers about 9.2 million square kilometres; only the polar deserts of Antarctica and the Arctic are larger."},{"id":"q5","question":"Which is the highest volcano on Earth above sea level?","options":[{"id":"a","text":"Cotopaxi","is_correct":false},{"id":"b","text":"Ojos del Salado","is_correct":true},{"id":"c","text":"Popocatépetl","is_correct":false},{"id":"d","text":"Mount Etna","is_correct":false}],"explanation":"Ojos del Salado rises 6,893 metres on the Chile-Argentina border, making it the world''s highest volcano."},{"id":"q6","question":"Which lake is the deepest on Earth, holding about a fifth of the world''s unfrozen fresh water?","options":[{"id":"a","text":"Lake Tanganyika","is_correct":false},{"id":"b","text":"Lake Baikal","is_correct":true},{"id":"c","text":"The Caspian Sea","is_correct":false},{"id":"d","text":"Great Slave Lake","is_correct":false}],"explanation":"Lake Baikal in Siberia reaches 1,642 metres deep and holds around a fifth of Earth''s surface fresh water."},{"id":"q7","question":"Which falls on the Argentina-Brazil border form the largest waterfall system in the world?","options":[{"id":"a","text":"Niagara Falls","is_correct":false},{"id":"b","text":"Victoria Falls","is_correct":false},{"id":"c","text":"Iguazú Falls","is_correct":true},{"id":"d","text":"Angel Falls","is_correct":false}],"explanation":"Iguazú''s roughly 275 individual falls stretch nearly three kilometres, crowned by the Devil''s Throat chasm."},{"id":"q8","question":"Which ocean trench contains the deepest known point on Earth, the Challenger Deep?","options":[{"id":"a","text":"The Tonga Trench","is_correct":false},{"id":"b","text":"The Peru-Chile Trench","is_correct":false},{"id":"c","text":"The Puerto Rico Trench","is_correct":false},{"id":"d","text":"The Mariana Trench","is_correct":true}],"explanation":"The Challenger Deep lies about 10,935 metres down in the Mariana Trench, deeper than Everest is tall."}]'::jsonb,
  null,
  array['geography', 'trivia', 'natural wonders', 'world records']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-maravillas-naturales',
  'Trivia de maravillas naturales: récords del planeta',
  'Ocho preguntas sobre las maravillas naturales más extremas del planeta: la catarata más alta, el lago más profundo y más récords.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"¿Cuál es el mayor sistema de arrecifes de coral de la Tierra, con unos 2.300 km frente a Queensland?","options":[{"id":"a","text":"El Arrecife Mesoamericano","is_correct":false},{"id":"b","text":"La Gran Barrera de Coral","is_correct":true},{"id":"c","text":"Los arrecifes del mar Rojo","is_correct":false},{"id":"d","text":"La barrera de Nueva Caledonia","is_correct":false}],"explanation":"La Gran Barrera de Coral reúne casi 3.000 arrecifes: es la mayor estructura creada por organismos vivos."},{"id":"q2","question":"¿Cuál es la cascada ininterrumpida más alta del mundo?","options":[{"id":"a","text":"Las cataratas del Iguazú","is_correct":false},{"id":"b","text":"Las cataratas del Niágara","is_correct":false},{"id":"c","text":"El Salto Ángel","is_correct":true},{"id":"d","text":"Las cataratas Victoria","is_correct":false}],"explanation":"El Salto Ángel cae 979 metros desde el tepuy Auyán, en el parque nacional Canaima de Venezuela."},{"id":"q3","question":"¿Qué cañón, excavado por el río Colorado, recorre unos 446 km por Arizona?","options":[{"id":"a","text":"El Gran Cañón","is_correct":true},{"id":"b","text":"El Cañón del Colca","is_correct":false},{"id":"c","text":"Las Barrancas del Cobre","is_correct":false},{"id":"d","text":"El Cañón del río Fish","is_correct":false}],"explanation":"Las capas de roca del Gran Cañón registran casi dos mil millones de años de historia de la Tierra."},{"id":"q4","question":"¿Cuál es el desierto cálido más grande de la Tierra?","options":[{"id":"a","text":"El desierto de Gobi","is_correct":false},{"id":"b","text":"El desierto de Atacama","is_correct":false},{"id":"c","text":"El desierto Arábigo","is_correct":false},{"id":"d","text":"El Sáhara","is_correct":true}],"explanation":"El Sáhara cubre unos 9,2 millones de kilómetros cuadrados; solo los desiertos polares de la Antártida y el Ártico son más extensos."},{"id":"q5","question":"¿Cuál es el volcán más alto del planeta sobre el nivel del mar?","options":[{"id":"a","text":"Cotopaxi","is_correct":false},{"id":"b","text":"Popocatépetl","is_correct":false},{"id":"c","text":"Ojos del Salado","is_correct":true},{"id":"d","text":"Etna","is_correct":false}],"explanation":"El Ojos del Salado se alza 6.893 metros en la frontera entre Chile y Argentina: es el volcán más alto del mundo."},{"id":"q6","question":"¿Qué lago es el más profundo de la Tierra y guarda cerca de una quinta parte del agua dulce no congelada?","options":[{"id":"a","text":"El lago Tanganica","is_correct":false},{"id":"b","text":"El mar Caspio","is_correct":false},{"id":"c","text":"El lago Baikal","is_correct":true},{"id":"d","text":"El Gran Lago del Esclavo","is_correct":false}],"explanation":"El lago Baikal, en Siberia, alcanza 1.642 metros de profundidad y contiene alrededor del 20 % del agua dulce superficial del planeta."},{"id":"q7","question":"¿Qué cataratas en la frontera entre Argentina y Brasil forman el mayor sistema de saltos de agua del mundo?","options":[{"id":"a","text":"Las cataratas del Niágara","is_correct":false},{"id":"b","text":"Las cataratas Victoria","is_correct":false},{"id":"c","text":"El Salto Ángel","is_correct":false},{"id":"d","text":"Las cataratas del Iguazú","is_correct":true}],"explanation":"Los cerca de 275 saltos del Iguazú se extienden por casi tres kilómetros, coronados por la garganta del Diablo."},{"id":"q8","question":"¿Qué fosa oceánica contiene el punto conocido más profundo de la Tierra, el abismo de Challenger?","options":[{"id":"a","text":"La fosa de Tonga","is_correct":false},{"id":"b","text":"La fosa Perú-Chile","is_correct":false},{"id":"c","text":"La fosa de Puerto Rico","is_correct":false},{"id":"d","text":"La fosa de las Marianas","is_correct":true}],"explanation":"El abismo de Challenger está a unos 10.935 metros en la fosa de las Marianas, más profundo que lo que mide el Everest."}]'::jsonb,
  null,
  array['geografía', 'trivia', 'maravillas naturales', 'récords mundiales']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

-- categories.quiz_count is maintained by the trigger on quizzes.

commit;
